INSERT INTO chapter_doctrine_knives VALUES (1, 5, 1, 1253, '第二刀', 'Ship BASBCMMetaPlasticity actor implementing the Bienenstock-Cooper-Munro 1982 rule:ΔW=α·pre·post·(post-θ) with θ adapting as sliding average of post² (homeostatic threshold)');
INSERT INTO chapter_doctrine_knives VALUES (1, 5, 2, 1254, '第三刀', '11 PROOF tests including the bedrock META-PLASTICITY proof: sustained high post activity raises θ monotonically toward mean(post²) → homeostatic stability against runaway potentiation');
