INSERT INTO chapter_doctrine_records VALUES (1, 10, 'phase2', 'chapter 四百七十四', 1272, 1275, 1275, 'chapter-474-v1-hot-path-attack-phase-1-entry', 'REAL HOT-PATH ATTACK phase 1 — first chapter that substantively closes 3 of the 6 directives the chapter 473 deep-review scored ≤4/10。 4 cuts (M1272-M1275)。 Cut 1 — ANE live MLComputeDevice binding behind opt-in factory (was 1/10 → now 5+/10 once hosts opt in)。 Cut 2 — registry-dispatch executor factory wires selectedKernelKey → registry dispatch with 5 typed outcomes (was 4/10 → now 6+/10)。 Cut 3 — end-to-end integration PROOF of the full chain (no chain test existed before)。 Cut 4 — chapter close-out + cross-doctrine sync。 ADR-016 → M1275。 V1 byte-equality preserved。 Branch on trajectory toward chapter 477''s default-mode flip。');
INSERT INTO chapter_doctrine_knives VALUES (1, 10, 0, 1272, '第一刀', 'BASANELiveReader closes the chapter 473 deep-review ''原生利用神经引擎 1/10'' gap。 NEW Sources/BASMetalSubstrate/BASANELiveReader.swift with a `.live()` factory that queries MLComputeDevice.allComputeDevices (iOS 17+/macOS 14+) + falls back to .conservative on simulator + watchOS。 Adopts thermal-state-aware derating。 7 tests PROOF including a real-device-gated assertion via XCTSkipUnless。');
INSERT INTO chapter_doctrine_knives VALUES (1, 10, 1, 1273, '第二刀', 'BASKernelRegistryDispatchExecutor closes the ''更硬核 (MPSGraph) 4/10'' gap。 NEW Sources/BASHostKit/BASKernelRegistryDispatchExecutor.swift with a makeRoutedExecutor factory that dispatches through BASMetalKernelRegistry when the scheduler''s assignment carries a kernel key + the kernel is registered + inputs buildable。 Typed outcome enum with 5 cases (dispatched + 4 fallback paths) lets tests + observability pin which path fired。 7 PROOF tests covering all 5 outcomes + replay-determinism。');
INSERT INTO chapter_doctrine_knives VALUES (1, 10, 2, 1274, '第三刀', 'End-to-end integration PROOF of the FULL hot-path chain: hint → scheduler → assignment → executor → registry → kernel.evaluate。 NEW Tests/BehavioralAISubstrateTests/BASKernelDispatchEndToEndIntegrationTests.swift。 4-stage plan walking stageA/C/J/K with EchoKernels registered under (op, float32, metalBuffer)。 PROOF that: 1) scheduler returns non-nil kernel keys when registry + capability align; 2) executor routes every stage through dispatched path; 3) replay-determinism holds across 2 repeat runs。 Before M1274 NO test exercised this full chain — the gap chapter 473 review surfaced is now closed with PROOF。');
INSERT INTO chapter_doctrine_knives VALUES (1, 10, 3, 1275, '第四刀', 'Chapter 474 close-out + Phase 2 bump (chapter 71→72, mNumberLast 1271→1275, commits 317→321) + ADR-016.M1271 → M1275。 Cross-doctrine sync of 6 mirror tests + 1 registry-frozen-hash refresh。 ADR-014 OPT-IN preserved at every commit boundary — V1 hot path untouched, V2 path additive only。');
