INSERT INTO chapter_doctrine_records VALUES (1, 11, 'phase2', 'chapter 四百七十五', 1276, 1279, 1279, 'chapter-475-v1-hot-path-attack-phase-2-echokernel-placeholder-closed', 'REAL HOT-PATH ATTACK phase 2 — closes the chapter 474 EchoKernel placeholder gap。 4 cuts (M1276-M1279)。 Cut 1 — BASCanonicalKernelInputBuilders typed factory namespace。 Cut 2 — FIRST PROOF that MPSGraph kernels actually compute correctly with 5 numerical tests。 Cut 3 — full chain end-to-end PROOF with REAL BASMPSGraphMatMulKernel (replaces EchoKernel stub)。 Cut 4 — chapter close-out。 ADR-016 → M1279。 ''更硬核'' now has SUBSTANTIVE evidence — not just kernels-exist-in-registry, but kernels-produce-correct-output。');
INSERT INTO chapter_doctrine_knives VALUES (1, 11, 0, 1276, '第一刀', 'BASCanonicalKernelInputBuilders typed factory namespace with matMul/rmsNorm/rotaryEmbedding input helpers + Float↔Data bit-exact pack/unpack helpers。 Closes the chapter 474 plannedFutureCut for ''chapter 478+: write input builders'' early。 6 tests PROOF including bit-exact round-trip。');
INSERT INTO chapter_doctrine_knives VALUES (1, 11, 1, 1277, '第二刀', 'BASMPSGraphMatMulIntegrationTests — FIRST test in the substrate where an MPSGraph kernel runs with REAL inputs and produces NUMERICALLY CORRECT output。 5 tests including 2×2 + 2×3×4 rectangular + identity sanity + execution-nanos contract pin。 The ''更硬核 4/10'' score from chapter 473 deep-review now has SUBSTANTIVE evidence — kernels don''t just register, they compute correctly。');
INSERT INTO chapter_doctrine_knives VALUES (1, 11, 2, 1278, '第三刀', 'BASKernelDispatchEndToEndRealKernelTests — sibling of M1274 chain test but with REAL BASMPSGraphMatMulKernel instead of EchoKernel stub。 Proves the FULL chain (hint → scheduler → assignment → executor → registry → MPSGraph dispatch → output) produces numerically correct [19,22,43,50] matmul result。 Closes the chapter 474 plannedFutureCut for EchoKernel placeholder replacement。');
INSERT INTO chapter_doctrine_knives VALUES (1, 11, 3, 1279, '第四刀', 'Chapter 475 close-out + Phase 2 bump (chapter 72→73, mNumberLast 1275→1279, commits 321→325) + ADR-016.M1275 → M1279。 Cross-doctrine sync of 6 mirror tests + 1 registry-frozen-hash refresh。 ADR-014 OPT-IN preserved。 V1 hot path untouched。');
