INSERT INTO chapter_doctrine_records VALUES (1, 12, 'phase2', 'chapter 四百七十六', 1280, 1283, 1283, 'chapter-476-v1-hot-path-attack-phase-3-bundle-migration-plus-kernel-coverage', 'REAL HOT-PATH ATTACK phase 3 — extends chapter 475 with broader kernel coverage + first real generic adoption。 4 cuts (M1280-M1283)。 Cut 1 — RMSNorm numerical correctness。 Cut 2 — FIRST real BASBundle<Item> typealias migration in the substrate (closes chapter 429 scaffold-without-migration gap)。 Cut 3 — RotaryEmbedding numerical correctness。 Cut 4 — chapter close-out。 ADR-016 → M1283。 3 of 4 MPSGraph kernels now have numerical PROOF。 First production-grade bundle adoption demonstrates the chapter 429 generic primitive is real,not just a scaffolding tag。');
INSERT INTO chapter_doctrine_knives VALUES (1, 12, 0, 1280, '第一刀', 'BASMPSGraphRMSNormIntegrationTests — extends M1277 numerical-correctness PROOF coverage from matMul to RMSNorm。 5 tests: 2×2 numerical correctness, 3-D identity weight, weight scaling, exec-nanos pin。');
INSERT INTO chapter_doctrine_knives VALUES (1, 12, 1, 1281, '第二刀', 'BASKernelDispatchOutcomeBundle — FIRST real BASBundle<Item> typealias migration in the substrate。 Closes part of chapter 473 ''低熵复杂系统 1/10'' with substantive evidence (not scaffolding)。 BASKernelDispatchOutcomeBundle = BASBundle<BASKernelDispatchOutcomeBundleItem> + convenience accessors (dispatchedCount / fallbackCount / dispatchedRatio / count(of:))。 5 PROOF tests。');
INSERT INTO chapter_doctrine_knives VALUES (1, 12, 2, 1282, '第三刀', 'BASMPSGraphRotaryEmbeddingIntegrationTests — third kernel numerical-correctness PROOF。 5 tests including identity rotation preserves input,90° rotation matches RoPE reference formula, 4-dim pair-wise rotation。 Coverage:matMul + rmsNorm + rotaryEmbedding (3 of 4 MPSGraph kernels now numerically verified)。');
