INSERT INTO chapter_doctrine_records VALUES (1, 15, 'phase2', 'chapter 四百七十九', 1292, 1295, 1295, 'chapter-479-phase-b-mpsgraph-kernels-7-of-8-coverage', 'REAL HOT-PATH ATTACK to 100% Phase B — 3 missing MPSGraph kernels shipped。 4 cuts (M1292-M1295)。 Cut 1 — softmax kernel (5-of-8)。 Cut 2 — layerNorm kernel (6-of-8)。 Cut 3 — conv2D kernel (7-of-8)。 Cut 4 — chapter close-out。 ADR-016 → M1295。 Only ssmScan deferred to Tier 2 — every other BASNeuralOp has numerical-correctness PROOF。 87.5% native op coverage achieved。 14 new PROOF tests covering uniform inputs + dominant elements + row-wise independence + sum-to-1 invariants + identity kernels + sum kernels。 V1 byte-equality preserved (additive kernel additions)。');
INSERT INTO chapter_doctrine_knives VALUES (1, 15, 0, 1292, '第一刀', 'BASMPSGraphSoftmaxKernel via `graph.softMax(with:axis:name:)`。 5-of-8 BASNeuralOp coverage。 5 PROOF tests:uniform input yields uniform output; dominant element approximation; row-wise independence;sum-to-1 invariant;execution-nanos contract。');
INSERT INTO chapter_doctrine_knives VALUES (1, 15, 1, 1293, '第二刀', 'BASMPSGraphLayerNormKernel via composed mean-centering + variance + rsqrt + scale + shift。 6-of-8 BASNeuralOp coverage。 5 PROOF tests: identity gamma+beta;beta shift;row mean = beta mean invariant;rank-2 shape pin; execution-nanos contract。');
INSERT INTO chapter_doctrine_knives VALUES (1, 15, 2, 1294, '第三刀', 'BASMPSGraphConv2DKernel via `graph.convolution2D(...)` with MPSGraphConvolution2DOpDescriptor (NHWC + HWIO + valid padding + stride 1)。 7-of-8 BASNeuralOp coverage。 4 PROOF tests:1x1 identity preserves input;2x2 ones-kernel sum; rank-4 shape validation; execution-nanos contract。');
INSERT INTO chapter_doctrine_knives VALUES (1, 15, 3, 1295, '第四刀', 'Chapter 479 close-out + Phase 2 bump (chapter 76→77, mNumberLast 1291→1295, commits 337→341) + ADR-016.M1291 → M1295。 Cross-doctrine sync + frozen hash refresh。 Only ssmScan (Mamba SSM) missing — deferred to Tier 2 chapter 496。');
