INSERT INTO chapter_doctrine_records VALUES (1, 16, 'phase2', 'chapter 四百八十', 1296, 1299, 1299, 'chapter-480-phase-c-ane-default-flipped-cache-observation-live', 'Phase C — ANE live binding default flip + MPSGraph cache observation layer + dispatch latency baseline measurement。 4 cuts (M1296-M1299)。 Cut 1 — probe default flipped (5-LOC change, 0 production caller break)。 Cut 2 — cache observation actor + 3rd BASBundle migration。 Cut 3 — 45×-gap baseline benchmark proves cache opportunity worth pursuing。 Cut 4 — close-out。 ADR-016 → M1299。 Per-kernel cache wiring deferred to future chapter where matMul kernel adopts the observation actor + stores MPSGraph references in its actor state。 V1 byte-equality preserved。');
INSERT INTO chapter_doctrine_knives VALUES (1, 16, 0, 1296, '第一刀', 'BASANECapabilityProbe default reader flipped from .conservative to BASANELiveReader.live() on iOS 17+/macOS 14+。 Conservative remains explicit factory (.conservativeReader()) for tests + simulator builds。 Zero production-caller breakage (Sources/ has 0 default constructors per chapter 477 audit)。');
INSERT INTO chapter_doctrine_knives VALUES (1, 16, 1, 1297, '第二刀', 'BASMPSGraphExecutableCache observation actor + BASMPSGraphCacheKey typed key + BASMPSGraphCacheObservationBundle as 3rd real BASBundle<Item> typealias migration。 8 PROOF tests covering equality / Codable round-trip / hit-miss recording / bundle ordering / accessor correctness / reset behavior。');
INSERT INTO chapter_doctrine_knives VALUES (1, 16, 2, 1298, '第三刀', 'BASMPSGraphDispatchLatencyBenchmark measures the cache opportunity:100× same-shape (250µs/call, 3.2% build overhead) vs 10× distinct shape (11.1 ms/call) = 45× gap proving cache-wiring is worth the complexity。 Cache observation actor integration test closes the loop with M1297。');
