INSERT INTO chapter_doctrine_records VALUES (1, 200, 'phase2', 'chapter 六百六十四', 2033, 2036, 2036, 'chapter-664-phase-j-mpsgraph-cache-wiring-storage-slot', 'Chapter 664 ships Phase J 第一刀 of wild-rolling-meerkat REAL HOT-PATH ATTACK resumption — `BASMPSGraphExecutableCache` gains MPSGraphExecutable storage slot enabling per-kernel compile-cost amortization。 3 new accessors at M2033 (cachedExecutable + storeExecutable + executableCount) + 7 PROOF tests at M2034 + NEW BASMPSGraphExecutableCacheWiringDoctrine at M2035 + close-out at M2036。 First plan-resumption chapter after 186 chapters of Codable gap-fill drift。 205 typed surfaces cumulative。 ADR-016 → M2036。 620 consecutive byte-equality clean commits。 V1 byte-equality preserved。 ADR-014 OPT-IN preserved。 Chapters 665-667 wire 6 MPSGraph kernels (rmsNorm + rotaryEmbedding + attention + softmax + layerNorm + conv2D) to consume the slot + ship 5× speedup wallclock benchmark。');
INSERT INTO chapter_doctrine_knives VALUES (1, 200, 0, 2033, '第一刀', 'BASMPSGraphExecutableCache gains MPSGraphExecutable storage slot — `cachedExecutable(forKey:)` + `storeExecutable(_:forKey:)` + `executableCount` accessors added。 reset() now drops cached executables alongside observations。');
INSERT INTO chapter_doctrine_knives VALUES (1, 200, 1, 2034, '第二刀', '7 PROOF tests via real MPSGraphExecutable compile + store + retrieve round-trip。 Includes M1297 observation regression guard。');
INSERT INTO chapter_doctrine_knives VALUES (1, 200, 2, 2035, '第三刀', 'NEW BASMPSGraphExecutableCacheWiringDoctrine + 30 anti-drift tests。 Pins Phase J goal,4-knife M-numbers, 3 new accessors,7 PROOF count,6-kernel wiring scope ahead, matMulExcludedFromCaching flag,5.0× speedup target,plan resumption markers。');
INSERT INTO chapter_doctrine_knives VALUES (1, 200, 3, 2036, '第四刀', 'Chapter 664 close-out + 13-file doctrine sync。 Phase J 第一刀 sealed — kernels in chapters 665-667 will consume the storage slot。 typed-surface 204 → 205。 V1 byte-equality preserved (cache is observation + amortization,not commitment)。');
