INSERT INTO chapter_doctrine_records VALUES (1, 201, 'phase2', 'chapter 六百六十五', 2037, 2040, 2040, 'chapter-665-phase-j-rmsnorm-rotary-embedding-cache-wired', 'Chapter 665 wires first 2 of 6 MPSGraph kernels to BASMPSGraphExecutableCache。 BASMPSGraphRMSNormKernel (5 PROOF tests) + BASMPSGraphRotaryEmbeddingKernel (4 PROOF tests) consume the M2033 storage slot via cache-on fast path while preserving M1169/M1190 baseline byte-equality when cache=nil。 NEW BASKernelCacheWiringPhaseJChapter665Doctrine + 29 anti-drift tests。 206 typed surfaces cumulative。 ADR-016 → M2040。 624 consecutive byte-equality clean commits。 V1 byte-equality preserved。 ADR-014 OPT-IN preserved。 Chapters 666-667 wire remaining 4 kernels (attention, softmax,layerNorm,conv2D) + ship the 5× speedup wallclock benchmark。');
INSERT INTO chapter_doctrine_knives VALUES (1, 201, 0, 2037, '第一刀', 'BASMPSGraphRMSNormKernel wired to BASMPSGraphExecutableCache。 Init adds optional cache param (default nil preserves M1169 baseline)。 evaluate() branches:cache=nil falls through to baseline graph.run path UNCHANGED;cache=non-nil uses compile-once + cached-executable.run fast path。 5 PROOF tests including byte-equality assertion between paths。');
