INSERT INTO chapter_doctrine_records VALUES (1, 238, 'phase2', 'chapter 七百四', 2179, 2182, 2182, 'chapter-704-metal-pilot-shipped', 'MULTI-LANGUAGE AUGMENTATION ARC METAL PILOT。 3rd of 5 risk-ascending per-language pilots。 M2179 第一刀 Package.swift switches BASMetalSubstrate target''s SSMScan.metal from exclude (chapter 699) to `resources: [.process(...)]` so SPM bundles .metal source into Bundle.module。 M2180 第二刀 NEW Sources/BASMetalSubstrate/BASMetalKernelLibraryLoader.swift actor loading + compiling via MTLLibrary.makeLibrary(source:options:) lazily + 5 typed error cases + memoization + #if canImport(Metal) watchOS stub + async make(flags:) factory。 M2181 第三刀 22 anti-drift tests including SPM .process() contract proof + V2 GPU-gated compile + memoization + identical-reference + 5 error case Codable round-trips;Diagnostic F pattern。 Chapter 704 close-out (M2182) + 13-file standard sync。 ADR-014 OPT-OUT preserved (metalKernelV2Enabled defaults FALSE → V1 kernel selection unchanged)。 ADR-016 → M2182。 764 consecutive byte-equality clean commits。 273 typed surfaces UNCHANGED (chapter 698 discipline honored across BOTH 702 + 703 + 704 pilots)。 60/60 score unchanged。 Substrate AT-REST + Tier A+B+C + 100% SIGBUS recovery + counter-sprawl trajectory preserved。 Next:chapter 七百五 C++ pilot M2183-M2186.');
INSERT INTO chapter_doctrine_knives VALUES (1, 238, 0, 2179, '第一刀', 'Package.swift switches BASMetalSubstrate target''s SSMScan.metal from `exclude: [...]` (chapter 699 silenced unhandled-file warning) to `resources: [.process(...)]` so SPM bundles the .metal source into Bundle.module。 Metal frameworks already platform-gated via linkerSettings;SPM .process() follows the same implicit gate via Bundle.module fallback on watchOS。');
INSERT INTO chapter_doctrine_knives VALUES (1, 238, 1, 2180, '第二刀', 'NEW Sources/BASMetalSubstrate/BASMetalKernelLibraryLoader.swift actor loading SSMScan.metal from Bundle.module + compiling via MTLLibrary.makeLibrary(source:options:) lazily on first request + memoization;5 typed BASMetalKernelLibraryLoaderError cases + Codable; #if canImport(Metal) gated stub for watchOS;async make(flags:) factory consulting metalKernelV2Enabled flag; V1 path throws .metalUnavailableOnPlatform to prevent accidental V2 library use。');
INSERT INTO chapter_doctrine_knives VALUES (1, 238, 2, 2181, '第三刀', '22 anti-drift tests in BASMetalKernelLibraryLoaderTests:resource bundling SPM .process() contract (7) + actor init flag honoring (3) + V1 path correctness (2: throws + no-memoize-pollute) + V2 GPU-gated compile/memoize/identical-reference (3 XCTSkipIf no-GPU) + error Codable round-trips preserve 5 cases + associated values (5) + flag factory (2); Diagnostic F pattern for 13 actor-touching tests。');
