INSERT INTO chapter_doctrine_knives VALUES (1, 244, 0, 2199, '第一刀', 'BASLanguageAugmentationFeatureFlags.swift gains NEW perFlagDefaults: [Flag: Bool] = [:] typed-surface constant + NEW effectiveDefault(for:) static function。 init() + init(initialState:) + isEnabled(_:) + resetAll() + allDefault() all consult effectiveDefault instead of raw defaultValue。 Enables granular future production wire-in。 Currently dict is EMPTY → V1 byte-equality preserved by construction。 8 new anti-drift tests including CRITICAL testPerFlagDefaultsConstantIsEmptyAtChapter710 doctrine-review trigger。');
