INSERT INTO chapter_doctrine_records VALUES (1, 245, 'phase2', 'chapter 七百十一', 2201, 2202, 2202, 'chapter-711-first-production-wire-in-sqlmigratorenabled', 'FIRST PRODUCTION WIRE-IN — chapter 七百十 planned-future-cut #1 fulfilled。 「全面 转向 多个 语言」 step 1 of 5 delivered。 2-knife chapter。 M2201 第一刀 perFlagDefaults flipped to `[.sqlMigratorEnabled: true]`。 Effect: hosts using factory pattern get V2 (generated schema) by default。 V1 still reachable via direct init or explicit opt-out。 chapter 七百二 PRAGMA byte-equality already proven safe。 12 anti-drift tests updated:default-init expectations + ADR-014 discipline test (now 4-of-5 pilots default-off) + factory test (V2-as-default + V1-reachable-via-explicit-opt-out) + 1 NEW production-wired pin acting as doctrine-review trigger for future revert。 M2202 第二刀 close-out + 13-file sync。 ADR-014 OPT-OUT preserved for 4 pilots;SQL pilot now opt-OUT not opt-IN。 ADR-016 → M2202。 784 consecutive byte-equality clean commits (V1 path code unchanged — chain measures V1 baseline)。 273 typed surfaces unchanged。 60/60 score unchanged。 Substrate AT-REST + Tier A+B+C + 100% SIGBUS recovery + counter-sprawl + zero-warning all preserved。 FIRST commit since chapter 七百一 / M2167 where non-V1 code runs in production for factory-pattern hosts。 Next: user direction — wire remaining 4 pilots OR specialize C++ cache OR pivot to different work。');
INSERT INTO chapter_doctrine_knives VALUES (1, 245, 0, 2201, '第一刀', 'BASLanguageAugmentationFeatureFlags.perFlagDefaults flipped from `[:]` empty (chapter 710 mechanism) to `[.sqlMigratorEnabled: true]` (FIRST production-wire-in)。 Hosts using BASMemoryUsageTracker.make(databaseURL:flags:) with default-init flag actor now get V2 path (generated multi-statement schema) by default。 V1 still reachable via direct init or explicit setFlag false。 chapter 七百二 / M2173 PRAGMA byte-equality proven。 12 anti-drift tests updated/renamed。');
