INSERT INTO chapter_doctrine_records VALUES (1, 256, 'phase2', 'chapter 七百二十二', 2223, 2224, 2224, 'chapter-722-error-type-case-identifier-global-uniqueness-matrix', 'ERROR (TYPE, CASE-IDENTIFIER) GLOBAL UNIQUENESS MATRIX for 5 pilots。 2-knife chapter。 M2223 第一刀 6 new tests verifying 22 type-prefixed tuples are globally unique + sanity check that known C++/Rust nullPointer collision is resolved by type prefix。 Extension of chapter 720 caseIdentifier work with cross-pilot disambiguation for telemetry pipelines。 M2224 第二刀 close-out + 13-file sync。 ADR-014 OPT-OUT preserved。 ADR-016 → M2224。 806 consecutive byte-equality clean commits。 273 typed surfaces unchanged。 60/60 score unchanged。 Auto-mode 1min cadence loop continues。');
INSERT INTO chapter_doctrine_knives VALUES (1, 256, 0, 2223, '第一刀', 'NEW BASFivePilotErrorTypeCaseIdentifierGlobalUniquenessTests.swift with 6 tests verifying the (typeName, caseIdentifier) tuple is globally unique across all 22 cases of the 5 pilot error enums。 Chapter 720 proved per-pilot identifier uniqueness but identifiers CAN collide ACROSS enums (e.g. both C++ and Rust have `.nullPointer` case)。 Type-prefixed tuple via String(describing: T.self) resolves cross-pilot collisions enabling telemetry pipelines to aggregate without losing per-pilot granularity。 All 6 tests pass。');
